#!/usr/bin/env bash
set -euo pipefail
GSZ=/opt/gsz
F1="$GSZ/routes/whatsapp.js"
F2="$GSZ/views/account/credentials.ejs"
F3="$GSZ/views/checkout.ejs"
TS=$(date +%Y%m%d-%H%M%S)
BK1="$F1.bak-step194-$TS"; BK2="$F2.bak-step194-$TS"; BK3="$F3.bak-step194-$TS"
echo "==> step194: wire renewal UI to the on-site engine"
cp "$F1" "$BK1"; cp "$F2" "$BK2"; cp "$F3" "$BK3"; echo "    backups taken"
restore(){ echo "!! restoring"; cp "$BK1" "$F1" 2>/dev/null||true; cp "$BK2" "$F2" 2>/dev/null||true; cp "$BK3" "$F3" 2>/dev/null||true; }
trap 'restore' ERR
echo "==> applying patcher"
P=$(mktemp /tmp/p194.XXXXXX.js); echo "" | base64 -d > "$P"
NODE_PATH="$GSZ/node_modules" node "$P" "$GSZ"
echo "==> validating"
NODE_PATH="$GSZ/node_modules" node --check "$F1" && echo "    whatsapp.js ok"
for V in "$F2" "$F3"; do NODE_PATH="$GSZ/node_modules" node -e "const ejs=require('ejs'),fs=require('fs');ejs.compile(fs.readFileSync('$V','utf8'),{filename:'$V'});console.log('    ejs ok: '+'$V'.replace('$GSZ/',''))"; done
echo "==> restarting"; pm2 restart gsz >/dev/null 2>&1 || pm2 restart gsz
CODE=000; for i in $(seq 1 25); do sleep 1; CODE=$(curl -s -o /dev/null -w '%{http_code}' http://127.0.0.1:3900/ || echo 000); [ "$CODE" = "200" ] && break; done
[ "$CODE" = "200" ] || { echo "    homepage $CODE"; false; }
echo "    homepage 200: OK (after ${i}s)"
rm -f "$P"; trap - ERR
echo ""
echo "==> step194 OK  Renewal is now fully on-site: the account credentials card's Renew buttons open /checkout?...&renew=<order> (WhatsApp only as fallback). Customer pays, we call /api/renew (credit-safe), poll, and deliver the new expiry on WhatsApp + email. Renewal engine is LIVE end to end."
